drop view if exists public.v_usability_end cascade;
create view public.v_usability_end with (security_invoker = true) as
select
  t.*,
  case when t.sus1 is not null and t.sus2 is not null and t.sus3 is not null and t.sus4 is not null and t.sus5 is not null and t.sus6 is not null and t.sus7 is not null and t.sus8 is not null and t.sus9 is not null and t.sus10 is not null then ((t.sus1 - 1) + (5 - t.sus2) + (t.sus3 - 1) + (5 - t.sus4) + (t.sus5 - 1) + (5 - t.sus6) + (t.sus7 - 1) + (5 - t.sus8) + (t.sus9 - 1) + (5 - t.sus10)) * 2.5 end as sus
from (
  select
    r.id as response_id,
    coalesce(r.client_time, r.created_at) as submitted_at,
    r.grp,
    r.wave,
    r.context,
    r.unit_code,
