drop view if exists public.v_student_screen cascade;
create view public.v_student_screen with (security_invoker = true) as
select
  t.*,
  case when (case when t.phq_1 is not null and t.phq_2 is not null and t.phq_9 is not null then (case when t.phq_3 is null and t.phq_4 is null and t.phq_5 is null and t.phq_6 is null and t.phq_7 is null and t.phq_8 is null then 1 else 0 end) end) = 1 then t.phq_1 + t.phq_2 + t.phq_9 when t.phq_1 is not null and t.phq_2 is not null and t.phq_3 is not null and t.phq_4 is not null and t.phq_5 is not null and t.phq_6 is not null and t.phq_7 is not null and t.phq_8 is not null and t.phq_9 is not null then t.phq_1 + t.phq_2 + t.phq_3 + t.phq_4 + t.phq_5 + t.phq_6 + t.phq_7 + t.phq_8 + t.phq_9 end as phq9,
  case when (case when t.gad_1 is not null and t.gad_2 is not null then (case when t.gad_3 is null and t.gad_4 is null and t.gad_5 is null and t.gad_6 is null and t.gad_7 is null then 1 else 0 end) end) = 1 then t.gad_1 + t.gad_2 when t.gad_1 is not null and t.gad_2 is not null and t.gad_3 is not null and t.gad_4 is not null and t.gad_5 is not null and t.gad_6 is not null and t.gad_7 is not null then t.gad_1 + t.gad_2 + t.gad_3 + t.gad_4 + t.gad_5 + t.gad_6 + t.gad_7 end as gad7,
  case when t.ptsd_gate = 0 then 0 when t.ptsd_1 is not null and t.ptsd_2 is not null and t.ptsd_3 is not null and t.ptsd_4 is not null and t.ptsd_5 is not null then t.ptsd_1 + t.ptsd_2 + t.ptsd_3 + t.ptsd_4 + t.ptsd_5 end as ptsd5,
  case when t.ac1 = 0 then 0 when t.ac1 is not null and t.ac2 is not null and t.ac3 is not null then t.ac1 + t.ac2 + t.ac3 end as auditc,
  case when t.la1 is not null and t.la2 is not null and t.la3 is not null and t.la4 is not null and t.la5 is not null and t.la6 is not null and t.la7 is not null and t.la8 is not null then t.la1 + t.la2 + t.la3 + t.la4 + t.la5 + t.la6 + t.la7 + t.la8 end as lifestress_a,
  case when t.brs1 is not null and t.brs2 is not null and t.brs3 is not null and t.brs4 is not null and t.brs5 is not null and t.brs6 is not null then t.brs1 + (6 - t.brs2) + t.brs3 + (6 - t.brs4) + t.brs5 + (6 - t.brs6) end as brs,
  case when t.av1 is not null and t.av2 is not null then t.av1 + t.av2 end as stakes,
  case when t.phq_1 is not null and t.phq_2 is not null and t.phq_9 is not null then (case when t.phq_3 is null and t.phq_4 is null and t.phq_5 is null and t.phq_6 is null and t.phq_7 is null and t.phq_8 is null then 1 else 0 end) end as phq9_short,
  case when t.gad_1 is not null and t.gad_2 is not null then (case when t.gad_3 is null and t.gad_4 is null and t.gad_5 is null and t.gad_6 is null and t.gad_7 is null then 1 else 0 end) end as gad7_short,
  case when (case when (case when t.phq_1 is not null and t.phq_2 is not null and t.phq_9 is not null then (case when t.phq_3 is null and t.phq_4 is null and t.phq_5 is null and t.phq_6 is null and t.phq_7 is null and t.phq_8 is null then 1 else 0 end) end) = 1 then t.phq_1 + t.phq_2 + t.phq_9 when t.phq_1 is not null and t.phq_2 is not null and t.phq_3 is not null and t.phq_4 is not null and t.phq_5 is not null and t.phq_6 is not null and t.phq_7 is not null and t.phq_8 is not null and t.phq_9 is not null then t.phq_1 + t.phq_2 + t.phq_3 + t.phq_4 + t.phq_5 + t.phq_6 + t.phq_7 + t.phq_8 + t.phq_9 end) is null then null when (case when (case when t.phq_1 is not null and t.phq_2 is not null and t.phq_9 is not null then (case when t.phq_3 is null and t.phq_4 is null and t.phq_5 is null and t.phq_6 is null and t.phq_7 is null and t.phq_8 is null then 1 else 0 end) end) = 1 then t.phq_1 + t.phq_2 + t.phq_9 when t.phq_1 is not null and t.phq_2 is not null and t.phq_3 is not null and t.phq_4 is not null and t.phq_5 is not null and t.phq_6 is not null and t.phq_7 is not null and t.phq_8 is not null and t.phq_9 is not null then t.phq_1 + t.phq_2 + t.phq_3 + t.phq_4 + t.phq_5 + t.phq_6 + t.phq_7 + t.phq_8 + t.phq_9 end) >= 10 then 1 else 0 end as phq9_pos,
  case when (case when (case when t.gad_1 is not null and t.gad_2 is not null then (case when t.gad_3 is null and t.gad_4 is null and t.gad_5 is null and t.gad_6 is null and t.gad_7 is null then 1 else 0 end) end) = 1 then t.gad_1 + t.gad_2 when t.gad_1 is not null and t.gad_2 is not null and t.gad_3 is not null and t.gad_4 is not null and t.gad_5 is not null and t.gad_6 is not null and t.gad_7 is not null then t.gad_1 + t.gad_2 + t.gad_3 + t.gad_4 + t.gad_5 + t.gad_6 + t.gad_7 end) is null then null when (case when (case when t.gad_1 is not null and t.gad_2 is not null then (case when t.gad_3 is null and t.gad_4 is null and t.gad_5 is null and t.gad_6 is null and t.gad_7 is null then 1 else 0 end) end) = 1 then t.gad_1 + t.gad_2 when t.gad_1 is not null and t.gad_2 is not null and t.gad_3 is not null and t.gad_4 is not null and t.gad_5 is not null and t.gad_6 is not null and t.gad_7 is not null then t.gad_1 + t.gad_2 + t.gad_3 + t.gad_4 + t.gad_5 + t.gad_6 + t.gad_7 end) >= 10 then 1 else 0 end as gad7_pos,
  case when (case when t.ptsd_gate = 0 then 0 when t.ptsd_1 is not null and t.ptsd_2 is not null and t.ptsd_3 is not null and t.ptsd_4 is not null and t.ptsd_5 is not null then t.ptsd_1 + t.ptsd_2 + t.ptsd_3 + t.ptsd_4 + t.ptsd_5 end) is null then null when (case when t.ptsd_gate = 0 then 0 when t.ptsd_1 is not null and t.ptsd_2 is not null and t.ptsd_3 is not null and t.ptsd_4 is not null and t.ptsd_5 is not null then t.ptsd_1 + t.ptsd_2 + t.ptsd_3 + t.ptsd_4 + t.ptsd_5 end) >= 3 then 1 else 0 end as ptsd5_pos,
  case when (case when t.ac1 = 0 then 0 when t.ac1 is not null and t.ac2 is not null and t.ac3 is not null then t.ac1 + t.ac2 + t.ac3 end) is null then null when (case when t.ac1 = 0 then 0 when t.ac1 is not null and t.ac2 is not null and t.ac3 is not null then t.ac1 + t.ac2 + t.ac3 end) >= 4 then 1 else 0 end as auditc_pos,
  case when t.fm_borrow in (1,2) then 1 when t.fm_borrow = 0 then 0 end as fm_informal,
  case when t.fm_borrow in (1,2) then (case when coalesce(t.sec_atm,0) + coalesce(t.sec_phone,0) + coalesce(t.sec_id,0) + coalesce(t.sec_doc,0) + coalesce(t.sec_item,0) > 0 then 1 else 0 end) when t.fm_borrow = 0 then 0 end as fm_security_any,
  case when t.fm_needs is null and (t.fm_share is null or t.fm_share = 9) then null when coalesce(t.fm_needs,0) >= 2 or coalesce(t.fm_share,0) between 2 and 3 then 1 else 0 end as fm_strain,
  case when t.sr_fees is not null or t.sr_lender is not null or t.sr_exams is not null or t.sr_away is not null or t.sr_homefight is not null or t.sr_health is not null or t.sr_future is not null or t.sr_loss is not null or t.sr_online is not null or t.sr_lonely is not null or t.sr_alcohol is not null or t.sr_safety is not null or t.sr_other is not null then coalesce(t.sr_fees,0) + coalesce(t.sr_lender,0) + coalesce(t.sr_exams,0) + coalesce(t.sr_away,0) + coalesce(t.sr_homefight,0) + coalesce(t.sr_health,0) + coalesce(t.sr_future,0) + coalesce(t.sr_loss,0) + coalesce(t.sr_online,0) + coalesce(t.sr_lonely,0) + coalesce(t.sr_alcohol,0) + coalesce(t.sr_safety,0) + coalesce(t.sr_other,0) end as sr_count
from (
  select
    r.id as response_id,
    coalesce(r.client_time, r.created_at) as submitted_at,
    r.grp,
    r.wave,
    r.context,
    r.unit_code,
    r.anon_code,
    r.protocol_version,
    r.risk_level,
    r.zone,
    (r.answers->>'age')::int as age,
    (r.answers->>'sex')::int as sex,
    (r.answers->>'prog')::int as prog,
    (r.answers->>'yos')::int as yos,
    (r.answers->>'apptype')::int as apptype,
    (r.answers->>'firstaway')::int as firstaway,
    (r.answers->>'prior_care')::int as prior_care,
    (r.answers->>'fam_loss')::int as fam_loss,
    (r.answers->>'phq_1')::int as phq_1,
