drop view if exists public.v_delphi cascade;
create view public.v_delphi with (security_invoker = true) as
select
  t.*
from (
  select
    r.id as response_id,
    coalesce(r.client_time, r.created_at) as submitted_at,
    r.grp,
    r.wave,
    r.context,
    r.unit_code,
    r.anon_code,
    r.protocol_version,
    r.risk_level,
    r.zone,
    (r.answers->>'dl_round')::int as dl_round,
    (r.answers->>'dl_role')::int as dl_role,
    (r.answers->>'dl1')::int as dl1,
    (r.answers->>'dl2')::int as dl2,
    (r.answers->>'dl3')::int as dl3,
    (r.answers->>'dl4')::int as dl4,
    (r.answers->>'dl5')::int as dl5,
    (r.answers->>'dl6')::int as dl6,
    (r.answers->>'dl7')::int as dl7,
    (r.answers->>'dl8')::int as dl8,
    (r.answers->>'dl9')::int as dl9,
    (r.answers->>'dl10')::int as dl10,
    (r.answers->>'dl11')::int as dl11,
    (r.answers->>'dl12')::int as dl12,
    (r.answers->>'dl13')::int as dl13,
    (r.answers->>'dl14')::int as dl14,
    (r.answers->>'dl15')::int as dl15,
    (r.answers->>'dl16')::int as dl16,
    (r.answers->>'dl17')::int as dl17,
    (r.answers->>'dl18')::int as dl18,
    (r.answers->>'dl19')::int as dl19,
    (r.answers->>'dl20')::int as dl20,
    (r.answers->>'dl21')::int as dl21,
    (r.answers->>'dl22')::int as dl22,
    (r.answers->>'dl23')::int as dl23,
    (r.answers->>'dl24')::int as dl24
  from public.responses r
  where r.form = 'delphi'
) t;
revoke all on public.v_delphi from anon, authenticated, public;
grant select on public.v_delphi to authenticated;

-- Free-text answers in long format, for qualitative coding. Remove any identifying detail before quoting.
create view public.v_free_text with (security_invoker = true) as
select r.id as response_id, coalesce(r.client_time, r.created_at) as submitted_at, r.form, r.grp, r.unit_code, r.protocol_version, 'sr_text'::text as item_id, r.answers->>'sr_text' as response_text from public.responses r where r.form = 'checkin' and coalesce(r.answers->>'sr_text','') <> ''
union all
select r.id as response_id, coalesce(r.client_time, r.created_at) as submitted_at, r.form, r.grp, r.unit_code, r.protocol_version, 'pl_text'::text as item_id, r.answers->>'pl_text' as response_text from public.responses r where r.form = 'pulse' and coalesce(r.answers->>'pl_text','') <> ''
union all
select r.id as response_id, coalesce(r.client_time, r.created_at) as submitted_at, r.form, r.grp, r.unit_code, r.protocol_version, 'd_text'::text as item_id, r.answers->>'d_text' as response_text from public.responses r where r.form = 'informant' and coalesce(r.answers->>'d_text','') <> ''
union all
select r.id as response_id, coalesce(r.client_time, r.created_at) as submitted_at, r.form, r.grp, r.unit_code, r.protocol_version, 'em_text'::text as item_id, r.answers->>'em_text' as response_text from public.responses r where r.form = 'informant' and coalesce(r.answers->>'em_text','') <> ''
union all
select r.id as response_id, coalesce(r.client_time, r.created_at) as submitted_at, r.form, r.grp, r.unit_code, r.protocol_version, 'ds_text'::text as item_id, r.answers->>'ds_text' as response_text from public.responses r where r.form = 'informant' and coalesce(r.answers->>'ds_text','') <> ''
union all
select r.id as response_id, coalesce(r.client_time, r.created_at) as submitted_at, r.form, r.grp, r.unit_code, r.protocol_version, 'ad_approve'::text as item_id, r.answers->>'ad_approve' as response_text from public.responses r where r.form = 'informant' and coalesce(r.answers->>'ad_approve','') <> ''
union all
select r.id as response_id, coalesce(r.client_time, r.created_at) as submitted_at, r.form, r.grp, r.unit_code, r.protocol_version, 'ad_top3'::text as item_id, r.answers->>'ad_top3' as response_text from public.responses r where r.form = 'informant' and coalesce(r.answers->>'ad_top3','') <> ''
union all
select r.id as response_id, coalesce(r.client_time, r.created_at) as submitted_at, r.form, r.grp, r.unit_code, r.protocol_version, 'ad_stop'::text as item_id, r.answers->>'ad_stop' as response_text from public.responses r where r.form = 'informant' and coalesce(r.answers->>'ad_stop','') <> ''
union all
select r.id as response_id, coalesce(r.client_time, r.created_at) as submitted_at, r.form, r.grp, r.unit_code, r.protocol_version, 'u_text'::text as item_id, r.answers->>'u_text' as response_text from public.responses r where r.form = 'usability_end' and coalesce(r.answers->>'u_text','') <> ''
union all
select r.id as response_id, coalesce(r.client_time, r.created_at) as submitted_at, r.form, r.grp, r.unit_code, r.protocol_version, 'sr_text'::text as item_id, r.answers->>'sr_text' as response_text from public.responses r where r.form = 'student_screen' and coalesce(r.answers->>'sr_text','') <> ''
union all
select r.id as response_id, coalesce(r.client_time, r.created_at) as submitted_at, r.form, r.grp, r.unit_code, r.protocol_version, 'sug1'::text as item_id, r.answers->>'sug1' as response_text from public.responses r where r.form = 'student_screen' and coalesce(r.answers->>'sug1','') <> ''
union all
