-- Delphi consensus by round: share rating 7 to 9 and median. Consensus rule in this study: 70% or more rate 7 to 9.
drop view if exists public.v_delphi_consensus;
create view public.v_delphi_consensus with (security_invoker = true) as
select d.dl_round as round, s.statement, count(s.score) as ratings,
       round(100.0 * avg(case when s.score >= 7 then 1 else 0 end) filter (where s.score is not null), 1) as pct_7_to_9,
       (percentile_cont(0.5) within group (order by s.score))::numeric(4,1) as median_score,
       (round(100.0 * avg(case when s.score >= 7 then 1 else 0 end) filter (where s.score is not null), 1) >= 70) as consensus_reached
from public.v_delphi d
cross join lateral (values
      ('dl1', d.dl1),
      ('dl2', d.dl2),
      ('dl3', d.dl3),
      ('dl4', d.dl4),
      ('dl5', d.dl5),
      ('dl6', d.dl6),
      ('dl7', d.dl7),
      ('dl8', d.dl8),
      ('dl9', d.dl9),
      ('dl10', d.dl10),
      ('dl11', d.dl11),
      ('dl12', d.dl12),
      ('dl13', d.dl13),
      ('dl14', d.dl14),
      ('dl15', d.dl15),
      ('dl16', d.dl16),
      ('dl17', d.dl17),
      ('dl18', d.dl18),
      ('dl19', d.dl19),
      ('dl20', d.dl20),
      ('dl21', d.dl21),
      ('dl22', d.dl22),
      ('dl23', d.dl23),
      ('dl24', d.dl24)
    ) as s(statement, score)
group by 1, 2;
revoke all on public.v_delphi_consensus from anon, authenticated, public;
grant select on public.v_delphi_consensus to authenticated;

-- Stressors people tick themselves, by unit and month (units with fewer than 10 people that month are hidden).
drop view if exists public.v_stressor_monthly;
create view public.v_stressor_monthly with (security_invoker = true) as
select coalesce(c.unit_code,'none') as unit_code, date_trunc('month', c.submitted_at)::date as month, s.stressor,
       count(distinct c.anon_code) filter (where s.ticked = 1) as people_ticking, count(*) filter (where s.ticked = 1) as times_ticked,
       round(100.0 * avg(s.ticked), 1) as pct_of_checkins
from public.v_checkin c
cross join lateral (values
      ('Money or debt', c.sr_money),
      ('Pressure from a lender or someone I owe', c.sr_lender),
      ('Posting, deployment or being away', c.sr_posting),
      ('Conflict or tension at home', c.sr_homefight),
      ('Children, school fees or family needs', c.sr_kids),
      ('My health or illness', c.sr_health),
      ('Work, leadership, discipline or workload', c.sr_work),
      ('A loss or bereavement', c.sr_loss),
      ('Things I see online or in the news', c.sr_online),
      ('Loneliness', c.sr_lonely),
      ('Alcohol', c.sr_alcohol),
      ('Fear for safety (on duty or at home)', c.sr_safety),
      ('Career, promotion or discharge', c.sr_career),
      ('Something else', c.sr_other)
    ) as s(stressor, ticked)
where c.sr_money is not null
group by 1, 2, 3
having count(distinct c.anon_code) >= 10;
revoke all on public.v_stressor_monthly from anon, authenticated, public;
grant select on public.v_stressor_monthly to authenticated;
